        if isinstance(obj, h5py.Dataset):
            out[name] = {'shape': obj.shape, 'dtype': str(obj.dtype), 'attrs': {k: str(v) for k, v in obj.attrs.items()}}
        else:
            out[name] = {'_type': 'group', 'attrs': {k: str(v) for k, v in obj.attrs.items()}}
    with h5py.File(path) as f:
        out['_root_attrs'] = {k: str(v) for k, v in f.attrs.items()}
